<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Abonelik yönetimi</title><link rel="stylesheet" href="/assets/app.css"></head>
<body><main class="container"><h1>Abonelik yönetimi</h1><p><a href="/admin">Yönetim paneli</a></p><?php if(!empty($_SESSION['success'])): ?><p class="success"><?= e($_SESSION['success']) ?></p><?php unset($_SESSION['success']); endif; ?><?php if(!empty($_SESSION['error'])): ?><p class="alert"><?= e($_SESSION['error']) ?></p><?php unset($_SESSION['error']); endif; ?>
<p>Bu ekran yalnızca ödeme dışarıda doğrulandıktan sonra manuel abonelik tanımlamak içindir. Henüz bir ödeme sağlayıcısına bağlı değildir.</p>
<h2>Abonelik etkinleştir</h2><form method="post" action="/admin/subscriptions/activate"><?= csrf_field() ?><label>Kullanıcı</label><select name="user_id" required><?php foreach($users as $user): ?><option value="<?= (int)$user['id'] ?>"><?= e($user['name']) ?> (<?= e($user['email']) ?>)</option><?php endforeach; ?></select><label>Paket</label><select name="plan_id" required><?php foreach($plans as $plan): ?><option value="<?= (int)$plan['id'] ?>"><?= e($plan['name']) ?> — <?= e($plan['price']) ?> <?= e($plan['currency']) ?> / <?= e($plan['billing_period']) ?></option><?php endforeach; ?></select><button type="submit">Aboneliği etkinleştir</button></form>
<h2>Abonelikler</h2><table><thead><tr><th>Kullanıcı</th><th>Paket</th><th>Durum</th><th>Başlangıç</th><th>Bitiş</th><th>Ödeme kaynağı</th><th></th></tr></thead><tbody><?php foreach($subscriptions as $subscription): ?><tr><td><?= e($subscription['user_name']) ?><br><?= e($subscription['email']) ?></td><td><?= e($subscription['plan_name']) ?></td><td><?= e($subscription['status']) ?></td><td><?= e($subscription['starts_at']) ?></td><td><?= e($subscription['ends_at']) ?></td><td><?= e($subscription['payment_provider']) ?></td><td><?php if($subscription['status']==='active'): ?><form method="post" action="/admin/subscriptions/cancel"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$subscription['id'] ?>"><button type="submit">İptal et</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></main></body></html>
